# 四维能力自查评分器: 组合价值由短板决定(见 l1 "能力组合"一节)
CAPS = {
    "judgment": "判断力",
    "design":   "系统设计",
    "verif":    "验证纪律",
    "domain":   "领域知识",
}
THRESHOLD = 3  # 每项 0-5 自评的最低及格线

def review(profile):
    """任一维度低于及格线, 整体即未就绪 —— 短板决定制。"""
    scores = {k: max(0, min(5, v)) for k, v in profile.items() if k in CAPS}
    weakest = min(scores, key=scores.get)
    below = [CAPS[k] for k in CAPS if scores.get(k, 0) < THRESHOLD]
    return {"weakest": CAPS[weakest], "floor": scores[weakest],
            "below_threshold": below,
            "ready_for_ai_native": not below}

ME = {"judgment": 4, "design": 3, "verif": 2, "domain": 5}
print(review(ME))
STRONG = {"judgment": 4, "design": 4, "verif": 4, "domain": 4}
print(review(STRONG))

